<?php elseif(in_array($g['stage'],['resumo','oferta'],true)): ?><article class="panel"><p class="tag">TEMPORADA CONCLUÍDA</p><h2>Uma temporada. Muitas histórias.</h2><p><?=e($summary['games'])?> jogos · <?=e($summary['goals'])?> gols · <?=e($summary['assists'])?> assistências · <?=e($summary['minutes'])?> minutos · nota média <?=e($summary['average'])?></p><a href="/classificacao">Ver classificação final →</a><?php if($g['stage']==='resumo'): ?><p>Desempenho e evolução pesam nas propostas. Subir um nível é possível; o caminho continua regional e fictício.</p><?php form('/transferencia/roleta',$g); ?><button class="btn btn-primary">Sortear proposta</button></form><?php else: ?><h3>Mercado de propostas</h3><?php wheel($g['offers']); ?><?php $sum=array_sum(array_column($g['offers'],'peso')); foreach($g['offers'] as $o): ?><p><?=e($o['club'])?> · <?=e(round($o['peso']/$sum*100,1))?>% <?=$o['selected']?'← proposta recebida':''?></p><?php endforeach ?><?php form('/transferencia/responder',$g); ?><button class="btn btn-primary" name="accept" value="yes">Aceitar e iniciar nova temporada</button><button class="btn btn-outline-light" name="accept" value="no">Recusar e permanecer</button></form><?php endif ?></article>
