<?php if($m['status']!=='em_andamento' || $m['minute']<$m['entry'] || $m['minute']>=$m['exit']): form('/partida/avancar',$g); ?><button class="btn btn-primary btn-lg">Avançar <?= $m['status']==='intervalo'?'para o segundo tempo':'a partida'?> →</button></form><?php else: ?><article class="panel"><h2><?=e(Game::situation($g)['text']??'O adversário se aproxima. O que você faz?')?></h2><?php form('/partida/decidir',$g); foreach(Game::choices($g) as $i=>$o): ?><button class="choice" name="option" value="<?=e($i)?>"><b><?=e(chr(65+$i))?></b><span><?=e($o['text'])?></span></button><?php endforeach ?></form></article><?php endif ?>
